#!/bin/bash
set -euo pipefail

# Sends the tokens generated by `generate.sh tokens` to the Blaze services of
# the openid-auth-limits-test and checks the responses. Tokens are never
# printed.
#
# Usage: check.sh <out-dir>

script_dir="$(dirname "$(readlink -f "$0")")"
. "$script_dir/../util.sh"

out="$1"
compose_file=".github/openid-auth-limits-test/docker-compose.yml"
invalid_token='Bearer realm="%s", error="invalid_token"'

headers_file=$(mktemp)
trap 'rm -f "$headers_file"' EXIT

# sends the token $2 (a file name in tokens, or empty for none) to the Blaze
# on port $1 and prints the status code
status() {
  if [ -n "$2" ]; then
    curl -s -H "Authorization: Bearer $(cat "$out/tokens/$2")" -D "$headers_file" -o /dev/null -w '%{response_code}' "http://localhost:$1/fhir"
  else
    curl -s -D "$headers_file" -o /dev/null -w '%{response_code}' "http://localhost:$1/fhir"
  fi
}

# checks that the token $2 is accepted by the Blaze on port $1
accepted() {
  echo "token $2 on port $1"
  test "status" "$(status "$1" "$2")" "200"
}

# checks that the token $2 is rejected by the Blaze on port $1 whose realm is $3
rejected() {
  echo "token $2 on port $1"
  test "status" "$(status "$1" "$2")" "401"
  # shellcheck disable=SC2059
  test "WWW-Authenticate header" "$(www_authenticate "$headers_file")" "$(printf "$invalid_token" "$3")"
}

# checks that the token $2 can't be checked by the Blaze on port $1, because it
# has no usable public key
unavailable() {
  echo "token $2 on port $1"
  test "status" "$(status "$1" "$2")" "503"
  test_empty "WWW-Authenticate header" "$(www_authenticate "$headers_file")"
}

# waits until the Blaze on port $1 accepts the token $2
wait_for_keys() {
  local i
  for i in $(seq 30); do
    if [ "200" = "$(status "$1" "$2")" ]; then return 0; fi
    echo "waiting for the public keys of the Blaze on port $1 ($i) ..."
    sleep 2
  done
  echo "🆘 the Blaze on port $1 didn't load its public keys"
  exit 1
}

# waits until the log of service $1 contains the fetch error and checks that
# it contains no key material
check_fetch_error() {
  local i logs
  for i in $(seq 30); do
    logs=$(docker compose -f "$compose_file" logs "$1")
    if grep -q "Error while fetching public key(s)" <<< "$logs"; then
      echo "✅ the log of $1 contains the fetch error"
      if grep -qF "$(cut -c1-40 "$out/k1-n")" <<< "$logs"; then
        echo "🆘 the log of $1 contains key material"
        exit 1
      fi
      echo "✅ the log of $1 contains no key material"
      return 0
    fi
    echo "waiting for the fetch error of $1 ($i) ..."
    sleep 2
  done
  echo "🆘 the log of $1 doesn't contain the fetch error"
  exit 1
}

#
# blaze-mixed (RFC mode)
#
port=8080
realm="http://provider/mixed"
wait_for_keys "$port" valid

echo "request without token on port $port"
test "status" "$(status "$port" "")" "401"
test "WWW-Authenticate header" "$(www_authenticate "$headers_file")" "Bearer realm=\"$realm\""

for token in valid typ-at-jwt aud-array kid-of-other-key by-16th-key \
  exp-30s-ago nbf-in-30s header-depth-8 payload-depth-8 number-32 name-256; do
  accepted "$port" "$token"
done

for token in by-k1024 by-k8200 by-e3 by-17th-key \
  alg-none alg-hs256 alg-rs256-lower crit hmac-public-key alg-none-unsigned jwk-attacker \
  flipped-signature flipped-payload \
  exp-missing exp-120s-ago nbf-in-120s \
  wrong-iss aud-missing aud-array-without \
  header-depth-9 payload-depth-9 number-33 name-257 header-duplicate payload-duplicate; do
  rejected "$port" "$token" "$realm"
done

#
# blaze-legacy
#
port=8086
wait_for_keys "$port" valid

for token in legacy-no-exp legacy-alg-none legacy-crit legacy-any-iss-aud; do
  accepted "$port" "$token"
done

rejected "$port" exp-30s-ago "Blaze"

echo "request without token on port $port"
test "status" "$(status "$port" "")" "401"
test "WWW-Authenticate header" "$(www_authenticate "$headers_file")" 'Bearer realm="Blaze"'

logs=$(docker compose -f "$compose_file" logs blaze-legacy)
for msg in \
  "OPENID_LEGACY_MODE is enabled. The legacy mode is deprecated" \
  "OPENID_PROVIDER_ISSUER is not set; issuer (iss) claim will not be validated." \
  "OPENID_AUDIENCE is not set; audience (aud) claim will not be validated."; do
  if grep -qF "$msg" <<< "$logs"; then
    echo "✅ the log of blaze-legacy contains: $msg"
  else
    echo "🆘 the log of blaze-legacy doesn't contain: $msg"
    exit 1
  fi
done

#
# document-level scenarios: the fetch fails, so Blaze has no key and answers
# requests with a token with 503
#
port=8081
for scenario in jwks-too-large jwks-too-deep jwks-duplicate-keys jwks-long-string config-too-large; do
  check_fetch_error "blaze-$scenario"
  unavailable "$port" "doc-$scenario"
  port=$(( port + 1 ))
done
